namespace OpenTPW;

/// <summary>
/// The kart and water track slice's approximation register (docs/TRACKS.md). Each entry is tagged <c>[APPROX:TRACK-NNN]</c> at its code site (a retired one leaves its BIN labels, a reclassified one an <c>[EXT:name]</c> decision, docs/TRACKS.md); the
/// words before the colon name the topic. Everything else of the slice is traced from the Mac and Windows binaries (BIN labels at the code sites).
/// </summary>
public static class TrackApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("TRACK-001", "TRACK-HEIGHT: the vehicles sample the object under each probe in the original's modes (0x450EA0: surface records, terrain + the header's +0xA0, the instance mesh), but the surface-record mode is taken for a model with a dummy record of type bit 2 (the instance block's bit 8 the original tests is not read), the terrain is the mean ground of the tile's (or bumper cell's) four corners instead of the triangle sampler 0x4527F0 at the probe, faces count from either side and are baked with the full rest transforms, a cell with no track gives the terrain, the instance-mesh mode reads every 0x8000 face of the model, and the Halloween and space kart stations (face-sampled station models) use the straight piece's floor; a tile stands on the mean ground of its four cells"),
		("TRACK-002", "TRACK-HMP: the .hmp height profile is the original's per-object height map (loader 0x451640 from the mesh loader 0x4629D0, rebuilt from the mesh by 0x451880 when missing or mis-sized); the vehicles' sampler does not read it (0x4511A0 samples faces or the terrain sampler 0x4527F0, the landscape's interpolated heights of the grid at [0x7A0854]+0x6C, 0 off the map, TRACK-001) and neither do OpenTPW's vehicles; the kit parses it; the map (+0xCC) is read by the cell-height lookup 0x452AE0 (the cell owner's map byte x 100/255 plus its base height, else the landscape; callers 0x45CDC0, 0x532FC0, 0x536CA0, 0x5370E0 and the tour code 0x55ABF0, 0x55C350, 0x55CC00, TOUR-005), and whether any other code reads the map is not traced"),
		("TRACK-003", "TRACK-OFFSET: each 20-unit tile turns about its own centre, where the original instances at the origin cell plus a one-cell offset by rotation (the Bumper.*Adjust keys are the controller-reference offsets of the ride placement 0x529E10, not a mesh pivot)"),
		("TRACK-004", "TRACK-X2LINK: the flow links of water crossings and tees are written as the original's line op does (0x539670: a tile with more than two arms ORs the line's direction into +0xD, so crossings get 0x14, 0x41, 0x50 or 0x05; the circuit walk 0x52A970 writes +0xD only at corners); not modelled: the clear op (ClearCell 0x53B280 -> 0x5227F0) removes the direction bits of a cleared line from a junction's link where OpenTPW removes the tile or counts the overlap down, and the other writers of +0xD (the type-25 walk 0x52BA50 takes the first linked arm by rotation, the edit sub-modes 0x52B400) have no counterpart"),
		("TRACK-005", "TRACK-STATION: the station is two tiles on the footprint's first two tile columns along the heading in the rows beside the entrance, the circuit starts at the first, and the station and finish buoys sit behind the station reference; the original's station is the line of 0x52A1A0 (two tiles of type 13 or 18 from the attraction cell, with the walk start and exit cell per rotation), which reads the attraction that is constructed at the placement's cursor cell (OpenTPW's anchor, 0x818C3C written at 0x528E12 from 0x528B44) plus the untraced per-rotation offset of 0x4D9CC0 (type +0x4B0, 0x529F86); that offset, the attraction's +8/+0xC and the line modes 0x80, 0x82 and 0x83 are not traced"),
		("TRACK-007", "TRACK-DEMOLISH: removing a kart or water ride refunds the track cell cost x the ride's scrap percentage / 100 per tile laid for it (ClearCell 0x53B280 credits it at 0x53B622 for a cleared type 11 or 16 tile; the replay runs with flag 0x81B46C = 1, so no end tile is skipped) and then charges 2 x the cell cost x the scrap percentage / 100 once (0x4D01F0, 0x528157..0x528179), both only for a type with Info.HasQueue (def+0x40) as the original; approximated: the original clears and refunds only what its two walks from the station reach (0x530830 forward and 0x530B70 backward record the circuit's corner points, at most 0x401, and 0x52FE50 replays the lines between them, a tile written again refunding on its last clearing visit), so a tile laid for the ride but cut off from its station stays and refunds nothing there, where OpenTPW removes and refunds every tile the ride owns"),
		("TRACK-008", "TRACK-ADDON: the track add-ons (Upgrades with AddOn.UpgradeType 1: jumps, tunnels, the chopper, the ogre and the Space Racers Teleport) are neither offered nor placed, so no tile gets map flag 0x10 and no section kind 12 or 13 is built; where the original sells them is not traced (the object window code around 0x481BC0..0x486D90 reads an add-on's ride through 0x4E2710), and the placement's cell writes for footprint codes 0xB/0x10 (0x528A70 → 0x532FC0) and the walk's switching of an add-on's class-1 dummies 1 and 0x10 are read but not built"),
		("TRACK-010", "TRACK-BRIDGE: a kart or water tile with at most two arms and no corner (straights, single-arm ends, armless tiles, 0x538AA4..0x538B05) is a bridge when it replaced path cells; the original tests the map layer under the track (a path or queue under any of its four cells, kept there and re-tested when a path is laid later) and only type 25 tests map types 2, 7 and 30 (cells outside the park); OpenTPW's track replaces the paths, so it remembers them when the tile is laid, writes no type 25, and takes the ahead and behind neighbours of the second pass from the flow link (an end or armless tile without a link along it takes the positive axis), whose PC twin is not traced"),
		("TRACK-014", "TRACK-WALK: the circuit walk is the original's 0x52A970 (heading kept on every non-corner cell, corners take mask ^ opposite and rewrite +0xD, 0-based steps to +0x24, failure on a non-track cell, fewer than two arms, a three-arm cell with type 0 or an armless track cell two ahead while the heading has bit 0x01, arrival at the start from any side, writes in both modes); not modelled: the readers of the step number +0x24 (0x53AEE6: the track tool's edit sub-modes 0xE and 0x13 at 0x5234D0, 0x524960, 0x527960 and 0x52B400, and its highlight), so the 0-based step and the side-entry arrival feed nothing here; the walk's step limit is OpenTPW's ([EXT:track-walk-step-limit])"),
		("TRACK-018", "TRACK-ANIM: the pieces' arm masks and their m clips play as the original triggers them (BUMP 17, the placement and line walks), but the track tool's edit sub-modes 0xE and 0x13, whose valid walk (0x526BD0) starts the pieces, have no counterpart, and the renderer draws texture-coordinate clips only (the Crypt Karts' bridge fires are texture-frame clips, so they would stay still)"),
		("TRACK-026", "TRACK-HEADS: a kart's riders are drawn as head sprites at the head dummies (class 0x100000B1, numbers 1 and 2) through the ride-head renderer in the original's seat order (rider list order, 0x549C60); the draw internals (0x0044B410, 0x00475A10) and the boarding guest between BUMP 1 and the car's creation are not traced"),
		("TRACK-032", "SAVED-RIDE CONTROLLER: a saved kart or water ride's controller is rebuilt from the saved circuit (BumpController.RestoreCircuit after a re-walk), where tp.exe's loader 0x543560 (called from 0x415270) restores the controller from the save stream and the ride's controller handle +0x28 then points at it; the stream's record layout, and whether the walk verdict is re-derived on load, are not traced (evidence needed: the record layout read by 0x543560)"),
	};
}
